import collections, statistics
def closures(ev, s, e, delta=800):
    W=[x for x in ev if s<=x[2]<=e]
    # adjacency: contact times
    adj=collections.defaultdict(list)
    for u,v,t in W:
        adj[u].append((v,t)); adj[v].append((u,t))
    res=[]
    # for each closing edge (a,b,t3) find common contact c with both times <= t3, max within delta
    for a,b,t3 in W:
        ca={}
        for x,t in adj[a]:
            if t<t3 and x!=b:
                ca.setdefault(x,[]).append(t)
        for x,t in adj[b]:
            if t<t3 and x!=a and x in ca:
                for ta in ca[x]:
                    m=max(ta,t)
                    if 0< t3-m <= delta:
                        res.append((a,b,t3,x,ta,t))
    return res
